package pe.eltumi.erp;
import org.springframework.web.bind.annotation.*;
import org.springframework.http.*;
import com.lowagie.text.*;
import com.lowagie.text.pdf.*;
import org.apache.poi.xssf.usermodel.XSSFWorkbook;
import java.io.*;
import java.util.*;
import java.util.List;
import java.math.*;
import java.nio.charset.StandardCharsets;
import static pe.eltumi.erp.Store.*;
@RestController @RequestMapping("/api")
public class ExportController {
 final Store db;final Catalog cat;final Access access;final ErpService erp;
 public ExportController(Store d,Catalog c,Access a,ErpService e){db=d;cat=c;access=a;erp=e;}
 ResponseEntity<byte[]> response(byte[] data,String mime,String filename){return ResponseEntity.ok().contentType(MediaType.parseMediaType(mime)).header("Content-Disposition",ContentDisposition.attachment().filename(filename,StandardCharsets.UTF_8).build().toString()).body(data);}
 @SuppressWarnings("unchecked") @GetMapping("/exports/{entity}.{format}")public ResponseEntity<byte[]> export(@PathVariable String entity,@PathVariable String format,@RequestParam(defaultValue="")String from,@RequestParam(defaultValue="")String to,@RequestParam(defaultValue="")String q,@RequestParam(defaultValue="")String status)throws Exception{access.entity(entity,"export");var rows=new ArrayList<Map<String,Object>>();int page=0;while(true){var data=erp.list(entity,q,status,from,to,page++,500);rows.addAll((List<Map<String,Object>>)data.get("items"));if(rows.size()>=((Number)data.get("total")).longValue())break;require(rows.size()<50000,"Filtra el reporte a menos de 50000 registros");}var fields=cat.fields(entity).stream().filter(f->!str(f,"type").equals("password")).toList();String title=str(cat.entity(entity),"title");
 if(format.equals("csv")){StringBuilder csv=new StringBuilder("\ufeff");csv.append(fields.stream().map(f->cell(str(f,"label"))).collect(java.util.stream.Collectors.joining(","))).append("\r\n");for(var row:rows)csv.append(fields.stream().map(f->cell(display(f,row))).collect(java.util.stream.Collectors.joining(","))).append("\r\n");return response(csv.toString().getBytes(StandardCharsets.UTF_8),"text/csv",entity+".csv");}
 if(format.equals("xlsx")){try(var workbook=new XSSFWorkbook();var out=new ByteArrayOutputStream()){var sheet=workbook.createSheet("El Tumi");var head=sheet.createRow(0);for(int i=0;i<fields.size();i++)head.createCell(i).setCellValue(str(fields.get(i),"label"));int index=1;for(var row:rows){var x=sheet.createRow(index++);for(int i=0;i<fields.size();i++){var f=fields.get(i);var c=x.createCell(i);if(List.of("money","number").contains(str(f,"type")))c.setCellValue(dec(row,str(f,"key")).doubleValue());else c.setCellValue(display(f,row));}}sheet.createFreezePane(0,1);for(int i=0;i<fields.size();i++)sheet.setColumnWidth(i,Math.min(11000,Math.max(4500,str(fields.get(i),"label").length()*320)));workbook.write(out);return response(out.toByteArray(),"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",entity+".xlsx");}}
 require(format.equals("pdf"),"Formato inválido");var selected=fields.stream().filter(f->!List.of("file","textarea").contains(str(f,"type"))).limit(8).toList();return response(tablePdf(title,selected.stream().map(f->str(f,"label")).toList(),rows.stream().map(r->selected.stream().map(f->display(f,r)).toList()).toList()),"application/pdf",entity+".pdf");}
 String display(Map<String,Object>f,Map<String,Object>row){String key=str(f,"key");if(f.containsKey("ref")&&id(row,key)>0){String ref=str(f,"ref");var value=db.get(ref,id(row,key));return str(value,"name").isBlank()?str(value,"code").isBlank()?"#"+id(row,key):str(value,"code"):str(value,"name");}return str(row,key);}
 String cell(String s){if(s.matches("^[=+@\\-].*"))s="'"+s;return "\""+s.replace("\"","\"\"")+"\"";}
 byte[] tablePdf(String title,java.util.List<String>head,java.util.List<java.util.List<String>>rows)throws Exception{var out=new ByteArrayOutputStream();var doc=new Document(PageSize.A4.rotate(),28,28,28,28);PdfWriter.getInstance(doc,out);doc.open();doc.add(new Paragraph("EL TUMI  /  "+title,FontFactory.getFont(FontFactory.HELVETICA_BOLD,18)));doc.add(new Paragraph("Generado: "+today()+"  |  Uso interno\n\n",FontFactory.getFont(FontFactory.HELVETICA,9)));var table=new PdfPTable(head.size());table.setWidthPercentage(100);for(String s:head){var c=new PdfPCell(new Phrase(s,FontFactory.getFont(FontFactory.HELVETICA_BOLD,9)));c.setBackgroundColor(new java.awt.Color(239,235,226));c.setPadding(6);table.addCell(c);}table.setHeaderRows(1);for(var row:rows)for(String s:row){var c=new PdfPCell(new Phrase(s,FontFactory.getFont(FontFactory.HELVETICA,8)));c.setPadding(5);table.addCell(c);}doc.add(table);doc.close();return out.toByteArray();}
 @GetMapping("/documents/{entity}/{id}.pdf")public ResponseEntity<byte[]> document(@PathVariable String entity,@PathVariable long id,@RequestParam(defaultValue="a4")String paper)throws Exception{access.entity(entity,"export");var row=db.get(entity,id);if(!entity.equals("invoices")){var fields=cat.fields(entity).stream().filter(f->!str(f,"type").equals("password")).toList();var rows=fields.stream().map(f->java.util.List.of(str(f,"label"),display(f,row))).toList();String title=str(cat.entity(entity),"title")+" #"+id;if(entity.equals("loans")&&str(row,"status").equals("PAGADO"))title="Constancia interna de no adeudo — préstamo #"+id;if(java.util.List.of("benefits","settlements").contains(entity))title+=" — estimación para revisión";return response(tablePdf(title,java.util.List.of("Concepto","Valor"),rows),"application/pdf",entity+"-"+id+".pdf");}
 var details=db.parseLines(str(row,"lines_snapshot"));Map<String,Object> company=db.json.readValue(str(row,"company_snapshot"),new com.fasterxml.jackson.core.type.TypeReference<>(){});boolean receipt=paper.equals("80mm");var out=new ByteArrayOutputStream();var document=new Document(receipt?new Rectangle(226.77f,Math.max(480,340+details.size()*45)):PageSize.A4,receipt?12:42,receipt?12:42,26,26);PdfWriter.getInstance(document,out);document.open();document.add(new Paragraph(str(company,"trade_name"),FontFactory.getFont(FontFactory.HELVETICA_BOLD,receipt?18:24)));document.add(new Paragraph(str(company,"name")+"\nRUC "+str(company,"ruc")+"\n"+str(company,"address"),FontFactory.getFont(FontFactory.HELVETICA,9)));document.add(new Paragraph("\nCOMPROBANTE INTERNO\nSIN VALIDEZ TRIBUTARIA",FontFactory.getFont(FontFactory.HELVETICA_BOLD,11)));document.add(new Paragraph(str(row,"number")+"  /  "+str(row,"status")+"\n"+str(row,"date")+"\nCliente: "+str(row,"customer")+"\nDocumento: "+str(row,"document")+"\nCondición: "+str(row,"payment_type")+"\n\n",FontFactory.getFont(FontFactory.HELVETICA,10)));var table=new PdfPTable(new float[]{5,1.4f,2});table.setWidthPercentage(100);for(String text:java.util.List.of("Detalle","Cant.","S/"))table.addCell(new Phrase(text,FontFactory.getFont(FontFactory.HELVETICA_BOLD,9)));for(var l:details)for(String text:java.util.List.of(str(l,"name"),dec(l,"quantity").stripTrailingZeros().toPlainString(),dec(l,"total").toPlainString()))table.addCell(new Phrase(text,FontFactory.getFont(FontFactory.HELVETICA,9)));document.add(table);document.add(new Paragraph("\nBase: S/ "+str(row,"subtotal")+"\nIGV: S/ "+str(row,"tax")+"\nTOTAL: S/ "+str(row,"total"),FontFactory.getFont(FontFactory.HELVETICA_BOLD,12)));if(str(row,"status").equals("ANULADO"))document.add(new Paragraph("Motivo: "+str(row,"cancel_reason")));document.add(new Paragraph("\nGracias por visitar El Tumi.\nDocumento generado para gestión interna. No ha sido enviado ni aceptado por SUNAT.",FontFactory.getFont(FontFactory.HELVETICA,8)));document.close();return response(out.toByteArray(),"application/pdf",str(row,"number")+(receipt?"-80mm":"")+".pdf");}
 @GetMapping("/invoices/{id}/payload")public Object payload(@PathVariable long id)throws Exception{access.module("sales","export");var i=db.get("invoices",id);var company=db.json.readValue(str(i,"company_snapshot"),new com.fasterxml.jackson.core.type.TypeReference<Map<String,Object>>(){});var lines=db.parseLines(str(i,"lines_snapshot"));BigDecimal taxable=BigDecimal.ZERO,exempt=BigDecimal.ZERO,unaffected=BigDecimal.ZERO;var details=new ArrayList<Map<String,Object>>();for(var l:lines){String type=str(l,"tax_type");if(type.equals("GRAVADO"))taxable=taxable.add(dec(l,"base"));else if(type.equals("EXONERADO"))exempt=exempt.add(dec(l,"base"));else unaffected=unaffected.add(dec(l,"base"));details.add(map("tipAfeIgv",type.equals("GRAVADO")?10:type.equals("EXONERADO")?20:30,"codProducto",l.get("code"),"unidad","NIU","descripcion",l.get("name"),"cantidad",l.get("quantity"),"mtoValorUnitario",dec(l,"base").divide(dec(l,"quantity"),6,RoundingMode.HALF_UP),"mtoValorVenta",l.get("base"),"mtoBaseIgv",type.equals("GRAVADO")?l.get("base"):0,"porcentajeIgv",l.get("tax_rate"),"igv",l.get("tax"),"totalImpuestos",l.get("tax"),"mtoPrecioUnitario",dec(l,"total").divide(dec(l,"quantity"),6,RoundingMode.HALF_UP)));}return map("estadoIntegracion","BORRADOR_NO_ENVIADO","ublVersion","2.1","tipoDoc",str(i,"document_type").equals("FACTURA")?"01":"03","tipoOperacion","0101","serie",i.get("series"),"correlativo",i.get("correlative"),"fechaEmision",str(i,"date")+"T00:00:00-05:00","formaPago",map("moneda","PEN","tipo",str(i,"payment_type").equals("CONTADO")?"Contado":"Credito"),"tipoMoneda","PEN","tipoCambio",1,"company",map("ruc",company.get("ruc"),"razonSocial",company.get("name"),"nombreComercial",company.get("trade_name"),"address",map("ubigueo",company.get("ubigeo"),"direccion",company.get("address"),"departamento",company.get("department"),"provincia",company.get("province"),"distrito",company.get("district"))),"client",map("tipoDoc",str(i,"document").length()==11?"6":str(i,"document").isBlank()?"0":"1","numDoc",i.get("document"),"rznSocial",i.get("customer"),"direccion",i.get("address")),"details",details,"mtoOperGravadas",taxable,"mtoOperExoneradas",exempt,"mtoOperInafectas",unaffected,"mtoIGV",i.get("tax"),"totalImpuestos",i.get("tax"),"valorVenta",i.get("subtotal"),"subTotal",i.get("total"),"mtoImpVenta",i.get("total"));}
 @GetMapping("/invoices/{id}/draft.xml") public ResponseEntity<byte[]> xml(@PathVariable long id)throws Exception{access.module("sales","export");var i=db.get("invoices",id);var lines=db.parseLines(str(i,"lines_snapshot"));Map<String,Object> company=db.json.readValue(str(i,"company_snapshot"),new com.fasterxml.jackson.core.type.TypeReference<>(){});StringBuilder x=new StringBuilder("<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<Invoice xmlns=\"urn:oasis:names:specification:ubl:schema:xsd:Invoice-2\" xmlns:cbc=\"urn:oasis:names:specification:ubl:schema:xsd:CommonBasicComponents-2\" xmlns:cac=\"urn:oasis:names:specification:ubl:schema:xsd:CommonAggregateComponents-2\">\n");x.append("<cbc:UBLVersionID>2.1</cbc:UBLVersionID><cbc:CustomizationID>2.0</cbc:CustomizationID>");x.append(tag("ID",str(i,"number"))).append(tag("IssueDate",str(i,"date"))).append(tag("InvoiceTypeCode",str(i,"document_type").equals("FACTURA")?"01":"03")).append(tag("Note","BORRADOR INTERNO SIN FIRMA DIGITAL. NO ENVIADO A SUNAT.")).append(tag("DocumentCurrencyCode","PEN"));x.append("<cac:AccountingSupplierParty><cac:Party><cac:PartyIdentification>").append(tag("ID",str(company,"ruc"))).append("</cac:PartyIdentification><cac:PartyLegalEntity>").append(tag("RegistrationName",str(company,"name"))).append("</cac:PartyLegalEntity></cac:Party></cac:AccountingSupplierParty>");x.append("<cac:AccountingCustomerParty><cac:Party><cac:PartyIdentification>").append(tag("ID",str(i,"document"))).append("</cac:PartyIdentification><cac:PartyLegalEntity>").append(tag("RegistrationName",str(i,"customer"))).append("</cac:PartyLegalEntity></cac:Party></cac:AccountingCustomerParty>");x.append("<cac:TaxTotal>").append(amountTag("TaxAmount",str(i,"tax"))).append("</cac:TaxTotal><cac:LegalMonetaryTotal>").append(amountTag("LineExtensionAmount",str(i,"subtotal"))).append(amountTag("TaxInclusiveAmount",str(i,"total"))).append(amountTag("PayableAmount",str(i,"total"))).append("</cac:LegalMonetaryTotal>");int n=1;for(var l:lines)x.append("<cac:InvoiceLine>").append(tag("ID",String.valueOf(n++))).append("<cbc:InvoicedQuantity unitCode=\"NIU\">").append(dec(l,"quantity").toPlainString()).append("</cbc:InvoicedQuantity>").append(amountTag("LineExtensionAmount",str(l,"base"))).append("<cac:TaxTotal>").append(amountTag("TaxAmount",str(l,"tax"))).append("</cac:TaxTotal><cac:Item>").append(tag("Description",str(l,"name"))).append("</cac:Item><cac:Price>").append(amountTag("PriceAmount",dec(l,"base").divide(dec(l,"quantity"),6,RoundingMode.HALF_UP).toPlainString())).append("</cac:Price></cac:InvoiceLine>");x.append("</Invoice>");return response(x.toString().getBytes(StandardCharsets.UTF_8),"application/xml",str(i,"number")+"-BORRADOR.xml");}
 String xmlEscape(String s){return s.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;").replace("'","&apos;");}String tag(String tag,String value){return "<cbc:"+tag+">"+xmlEscape(value)+"</cbc:"+tag+">";}String amountTag(String tag,String value){return "<cbc:"+tag+" currencyID=\"PEN\">"+xmlEscape(value)+"</cbc:"+tag+">";}
}
